using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputBeamStemProof {
 static List<float[]> Read(byte[] b,int count){var rows=new List<float[]>();int at=0;for(int i=0;i<count;i++){int n=(int)BitConverter.ToSingle(b,at);var p=new float[n];Buffer.BlockCopy(b,at+4,p,0,n*4);rows.Add(p);at+=(n+1)*4;}return rows;}
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),ss=File.ReadAllBytes(a[1]);int sp=int.Parse(a[2]),offset=BitConverter.ToUInt16(ss,sp+4),first=BitConverter.ToInt16(ds,offset),count=BitConverter.ToInt16(ds,0x80d2);var before=Read(File.ReadAllBytes(a[3]),count);var expected=Read(File.ReadAllBytes(a[4]),count);var result=InputBeamStemCompletion.Apply(before,first);int words=0;for(int i=0;i<count;i++){if(result[i].Length!=expected[i].Length)throw new Exception("Length "+i);for(int p=0;p<result[i].Length;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(result[i][p]),0)!=BitConverter.ToInt32(BitConverter.GetBytes(expected[i][p]),0))throw new Exception("Item "+(i+1)+" P"+(p+1)+": "+result[i][p]+" != "+expected[i][p]);words++;}}Console.WriteLine("PASS "+words+" original compact-item words through beam stem completion; firstItem="+first);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
